package cn.campus.schedule;
import android.app.*;
import android.widget.*;
import org.json.*;
import java.time.LocalDate;
import java.util.*;

final class ChatUi {
    static void menu(AiActivity a){new AlertDialog.Builder(a).setTitle("对话管理").setItems(new String[]{"＋ 新建对话","切换对话","重命名当前对话","删除当前对话","清空当前对话"},(d,w)->{if(w==0)name(a,true);if(w==1){JSONArray all=a.chats.all();String[] names=new String[all.length()];for(int i=0;i<all.length();i++)names[i]=all.optJSONObject(i).optString("title");new AlertDialog.Builder(a).setTitle("切换对话").setItems(names,(v,n)->a.switchSession(all.optJSONObject(n).optString("id"))).show();}if(w==2)name(a,false);if(w>=3)new AlertDialog.Builder(a).setTitle(w==3?"删除当前对话？":"清空当前对话？").setMessage("已经保存到日程和心情的内容会保留。").setNegativeButton("取消",null).setPositiveButton(w==3?"删除":"清空",(v,n)->{a.stopRequest();a.storeHistory();if(w==3)a.chats.delete(a.sessionId,LocalDate.now());else{AgendaFeatures.put(a.chats.active(),"history",new JSONArray());AgendaFeatures.put(a.chats.active(),"draft","");a.chats.save();}a.loadSession();a.render();}).show();}).show();}
    static void name(AiActivity a,boolean create){LinearLayout f=a.form();EditText input=a.field(f,"对话名称",create?"":a.chats.active().optString("title"));a.dialog(create?"新建对话":"重命名对话",f,()->{String name=input.getText().toString().trim();if(name.isEmpty()||name.length()>60)throw new IllegalArgumentException("请输入 1–60 字的对话名称");a.storeHistory();if(create){a.stopRequest();a.chats.create(name,a.from);a.loadSession();}else{AgendaFeatures.put(a.chats.active(),"title",name);a.chats.save();}}).show();}
    static void context(AiActivity a){LinearLayout f=a.form();Switch data=new Switch(a);data.setText("读取 App 日程与心情资料");data.setChecked(a.readApp);f.addView(data);Spinner history=new Spinner(a);history.setContentDescription("聊天历史范围");String[] labels={"不携带历史，只发当前消息","最近 20 条消息","最近 50 条消息","最近 100 条消息"};int[] limits={0,20,50,100};history.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,labels));for(int i=0;i<limits.length;i++)if(limits[i]==a.historyLimit)history.setSelection(i);f.addView(history);f.addView(a.text("设置仅作用于当前对话。关闭资料读取不会删除之前已聊过的内容；需要隔离时请新建对话。",13,a.MUTED,false));f.addView(a.action("选择哪些历史消息可以发送",()->messages(a)));a.dialog("当前对话上下文",f,()->{a.readApp=data.isChecked();a.historyLimit=limits[history.getSelectedItemPosition()];if(!a.readApp)a.selectedPhotos.clear();a.storeHistory();}).show();}
    static void messages(AiActivity a){String[] names=new String[a.history.length()];boolean[] checked=new boolean[names.length];for(int i=0;i<names.length;i++){JSONObject m=a.history.optJSONObject(i);String value=m.optString("text").replace('\n',' ');names[i]=(m.optString("role").equals("user")?"我：":"AI：")+value.substring(0,Math.min(60,value.length()));checked[i]=!m.optBoolean("excluded");}new AlertDialog.Builder(a).setTitle("允许携带的历史消息").setMultiChoiceItems(names,checked,(d,n,on)->checked[n]=on).setPositiveButton("确定",(d,w)->{for(int i=0;i<names.length;i++)AgendaFeatures.put(a.history.optJSONObject(i),"excluded",!checked[i]);a.storeHistory();}).setNegativeButton("取消",null).show();}
}
